options.customCss:
@import url("https://fonts.googleapis.com/css2?family=Orbitron:wght@700;900&display=swap");
:root {
  --chat--color-primary: #00f0ff;
  --chat--color-primary-shade-50: #00c8d6;
  --chat--color-primary-shade-100: #00a0ad;
  --chat--color-secondary: #39ff14;
  --chat--color-secondary-shade-50: #2ed610;
  --chat--color-white: #0a0a0f;
  --chat--color-light: #0d0d14;
  --chat--color-light-shade-50: #14141f;
  --chat--color-light-shade-100: #1c1c2b;
  --chat--color-medium: #2a2a3d;
  --chat--color-dark: #e0fbff;
  --chat--color-typing: #00f0ff;
  --chat--border-radius: 14px;
  --chat--header--background: linear-gradient(135deg, #05050a 0%, #0b1a24 100%);
  --chat--header--color: #00f0ff;
  --chat--heading--font-size: 1.8em;
  --chat--subtitle--line-height: 1.6;
  --chat--body--background: #0a0a0f;
  --chat--footer--background: #05050a;
  --chat--footer--color: #e0fbff;
  --chat--message--bot--background: #12121c;
  --chat--message--bot--color: #e0fbff;
  --chat--message--bot--border: 1px solid #00f0ff55;
  --chat--message--user--background: #39ff14;
  --chat--message--user--color: #05050a;
  --chat--input--border-active: 1px solid #00f0ff;
  --chat--input--background: #12121c;
  --chat--input--text-color: #ffffff;
  --chat--input--placeholder-color: #8fd8e0;
  --chat--input--send--button--color: #00f0ff;
  --chat--input--send--button--color-hover: #39ff14;
  --chat--toggle--background: #00f0ff;
  --chat--toggle--hover--background: #39ff14;
  --chat--toggle--active--background: #00a0ad;
}
body, .chat-layout { background: #0a0a0f; }
.chat-header { border-bottom: 1px solid #00f0ff; box-shadow: 0 0 18px #00f0ff66; }
.chat-header h1 { font-family: "Orbitron", "Segoe UI", sans-serif; letter-spacing: 4px; font-weight: 900; text-transform: uppercase; background: linear-gradient(90deg, #ff2bd6 0%, #b026ff 50%, #00f0ff 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; color: #ff2bd6; filter: drop-shadow(0 0 6px #ff2bd6aa) drop-shadow(0 0 14px #00f0ff66); }
.chat-header p { color: #39ff14; text-shadow: 0 0 6px #39ff1488; }
.chat-message-from-bot { box-shadow: 0 0 10px #00f0ff33; }
.chat-message-from-user { box-shadow: 0 0 12px #39ff1466; }
.chat-inputs, .chat-input, .chat-footer { background: #05050a !important; }
.chat-inputs textarea, .chat-input textarea, .chat-footer textarea, textarea { background: #12121c !important; color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; caret-color: #00f0ff !important; border: 1px solid #00f0ff88 !important; font-size: 15px; }
.chat-inputs textarea::placeholder, .chat-input textarea::placeholder, textarea::placeholder { color: #8fd8e0 !important; -webkit-text-fill-color: #8fd8e0 !important; opacity: 1; }
